import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))

        count = [0] * (n + 1)

        for _ in range(n):
            a = int(next(iterator))
            b = int(next(iterator))
            count[a] += 1
            count[b] += 1

        possible = True
        for x in range(1, n + 1):
            if count[x] > 2:
                possible = False
                break

        if possible:
            results.append("YES")
        else:
            results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
